{"command":"cat << 'EOF' > tree_script.py
def print_tree(nodes):
    # nodes is list of (level, text)
    # first convert to tree structure
    class Node:
        def __init__(self, level, text):
            self.level = level
            self.text = text
            self.children = []

    roots = []
    stack = []

    for level, text in nodes:
        node = Node(level, text)
        while stack and stack[-1].level >= level:
            stack.pop()

        if stack:
            stack[-1].children.append(node)
        else:
            roots.append(node)
        stack.append(node)

    def render(node, prefix, is_last):
        connector = "└──" if is_last else "├──"
        print(f"{prefix}{connector}{node.text}")

        for i, child in enumerate(node.children):
            child_is_last = i == len(node.children) - 1
            extension = "   " if is_last else "│  "
            render(child, prefix + extension, child_is_last)

    for i, root in enumerate(roots):
        render(root, "", i == len(roots) - 1)

nodes = [
    (1, "# H1"),
    (2, "## H2"),
    (2, "## H2_2"),
    (3, "### H3"),
    (2, "## H2_3")
]
print_tree(nodes)
EOF
