{"command":"cat << 'EOF' > parse_md.py
import re

def parse_markdown(lines):
    headings = []
    in_code = False
    for i, line in enumerate(lines):
        if line.startswith('```') or line.startswith('~~~'):
            in_code = not in_code
            continue
        if in_code:
            continue

        m = re.match(r'^(#{1,6})\s+(.*)', line)
        if m:
            level = len(m.group(1))
            text = m.group(2).strip()
            headings.append({
                'level': level,
                'text': text,
                'raw': line.strip(),
                'line': i + 1,
                'offset': sum(len(l) for l in lines[:i])
            })
    return headings
