{"command":"cat << 'EOF' > query_engine.py
import re

def evaluate_query(query, lines):
    # parse document
    headings = []
    code_blocks = []
    links = []

    in_code = False
    current_code = []
    for line in lines:
        if line.startswith('```') or line.startswith('~~~'):
            if in_code:
                current_code.append(line)
                code_blocks.append('\n'.join(current_code))
                current_code = []
            else:
                current_code.append(line)
            in_code = not in_code
            continue

        if in_code:
            current_code.append(line)
            continue

        m = re.match(r'^(#{1,6})\s+(.*)', line)
        if m:
            level = len(m.group(1))
            headings.append({'level': level, 'text': line.strip()})

        urls = re.findall(r'\[.*?\]\((.*?)\)', line)
        for u in urls:
            links.append(u)

    # Process query
    q = query.strip()
    res = []

    # Pipeline
    parts = [p.strip() for p in q.split('|')]

    # Selection part
    sel = parts[0]
    if sel == '.h' or sel == '[.h]':
        res = [h['text'] for h in headings]
    elif sel.startswith('.h') and len(sel) > 2 and sel[2].isdigit():
        level = int(sel[2])
        if '[' in sel and ']' in sel:
            term = sel[sel.index('[')+1:sel.index(']')]
            res = [h['text'] for h in headings if h['level'] == level and term.lower() in h['text'].lower()]
        else:
            res = [h['text'] for h in headings if h['level'] == level]
    elif sel.startswith('[.h') and len(sel) > 3 and sel[3].isdigit():
        level = int(sel[3])
        res = [h['text'] for h in headings if h['level'] == level]
    elif sel == '.code' or sel.startswith('.code['):
        res = code_blocks
    elif sel == '.link' or sel.startswith('.link['):
        # We only support links | url for now
        if len(parts) > 1 and parts[1] == 'url':
            res = links
            parts.pop(1)
        else:
            # what if they just query .link? we should return markdown links, which we didn't parse.
            pass
    elif '>' in sel:
        # e.g., .h1[Features] > .h2
        left, right = sel.split('>')
        left = left.strip()
        right = right.strip()
        if left.startswith('.h') and right.startswith('.h'):
            # simple hierarchy
            level_left = int(left[2])
            term_left = left[left.index('[')+1:left.index(']')] if '[' in left else None
            level_right = int(right[2])

            under_left = False
            for h in headings:
                if h['level'] == level_left:
                    under_left = (term_left is None) or (term_left.lower() in h['text'].lower())
                elif h['level'] <= level_left:
                    under_left = False

                if under_left and h['level'] == level_right:
                    res.append(h['text'])

    # Pipes part
    for p in parts[1:]:
        if p == 'count':
            res = [str(len(res))]
        elif p == 'text':
            res = [re.sub(r'^#{1,6}\s+', '', r) for r in res]
        elif p.startswith('select(contains('):
            term = p.split('"')[1]
            res = [r for r in res if term.lower() in r.lower()]

    return res

if __name__ == '__main__':
    with open('test4.md') as f:
        lines = f.read().splitlines()
    print(evaluate_query('.h1[Features] > .h2', lines))
    print(evaluate_query('.h2 | text', lines))
EOF
