    headings = []
    in_code = False
    for i, line in enumerate(lines):
        if line.startswith('```') or line.startswith('~~~'):
            in_code = not in_code
            continue
        if in_code:
            continue
        m = re.match(r'^(#{1,6})\s+(.*)', line)
        if m:
            level = len(m.group(1))
            headings.append({'level': level, 'text': line.strip(), 'raw_text': m.group(2).strip()})
    return headings

def tree_printer(headings):
    class Node:
        def __init__(self, level, text):
            self.level = level
            self.text = text
            self.children = []
    roots = []
    stack = []
    for h in headings:
        node = Node(h['level'], h['text'])
        while stack and stack[-1].level >= h['level']:
            stack.pop()
        if stack:
            stack[-1].children.append(node)
        else:
            roots.append(node)
        stack.append(node)

    def render(node, prefix, is_last, is_root):
        connector = "└──" if is_last else "├──"
        print(f"{prefix}{connector}{node.text}")
        for i, child in enumerate(node.children):
            child_is_last = i == len(node.children) - 1
            extension = "   " if is_last else "│  "
            if is_root:
                extension = "   " if is_last else "│  "
            render(child, prefix + extension, child_is_last, False)

    for i, root in enumerate(roots):
        render(root, "", i == len(roots) - 1, True)

def count_headings(headings):
    counts = {i: 0 for i in range(1, 7)}
    for h in headings:
        counts[h['level']] += 1

    print("Heading counts:")
    for i in range(1, 7):
        if counts[i] > 0:
            print(f"  {'#' * i}: {counts[i]}")
    print(f"\nTotal: {len(headings)}")

def main():
    args = sys.argv[1:]

    if not args:
        if not sys.stdout.isatty():
            err_msg()
        else:
            print("treemd TUI")
            sys.exit(0)

    if '-h' in args or '--help' in args:
        print_help()
        sys.exit(0)

    if '-V' in args or '--version' in args:
        print("treemd 0.5.7")
        sys.exit(0)

    if '--query-help' in args:
        print_query_help()
        sys.exit(0)

    if '--setup-completions' in args:
        print("Error setting up completions: Could not detect shell\nShell Completion Setup Instructions\n\nAdd the appropriate line to your shell config:\n\nBash (~/.bashrc):\n  source <(COMPLETE=bash treemd)\n\nZsh (~/.zshrc):\n  source <(COMPLETE=zsh treemd)\n\nFish (~/.config/fish/config.fish):\n  COMPLETE=fish treemd | source\n\nAfter adding the line, restart your shell or source the config file.", file=sys.stderr)
        sys.exit(1)

    opts = {'list': False, 'tree': False, 'filter': None, 'level': None,
            'output': 'plain', 'section': None, 'count': False, 'query': None,
            'query_output': 'plain', 'files': []}
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-l', '--list'): opts['list'] = True
        elif a == '--tree': opts['tree'] = True
        elif a in ('-L', '--level'):
            opts['level'] = int(args[i+1]); i+=1
        elif a in ('-o', '--output'):
            opts['output'] = args[i+1]; i+=1
        elif a in ('-s', '--section'):
            opts['section'] = args[i+1]; i+=1
        elif a == '--count': opts['count'] = True
        elif a == '--filter':
            opts['filter'] = args[i+1]; i+=1
        elif a in ('-q', '--query'):
            opts['query'] = args[i+1]; i+=1
        elif a == '--query-output':
            opts['query_output'] = args[i+1]; i+=1
        elif a in ('--theme', '--color-mode'): i+=1
        elif a in ('--no-images', '--images'): pass
        elif not a.startswith('-'):
            opts['files'].append(a)
        else:
            print(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: executable [OPTIONS] [FILE]... [COMMAND]\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        i += 1

    if not opts['files'] and not opts['query']:
        pass

    file_to_read = opts['files'][0] if opts['files'] else '-'
    try:
        if file_to_read == '-':
            content = sys.stdin.read()
        else:
            with open(file_to_read, 'r') as f:
                content = f.read()
    except Exception as e:
        print(f"Error reading input: I/O error: No such file or directory (os error 2)", file=sys.stderr)
        sys.exit(1)

    if not any([opts['list'], opts['tree'], opts['count'], opts['section'], opts['query']]):
        if not sys.stdout.isatty():
            err_msg()
        else:
            sys.exit(0)

    headings = parse_markdown(content)

    if opts['section']:
        sec = opts['section'].lower()
        found = False
        target_level = 0
        extracted = []
        in_code = False
        for line in content.splitlines():
            if line.startswith('```') or line.startswith('~~~'):
                in_code = not in_code
            m = re.match(r'^(#{1,6})\s+(.*)', line)
            if not in_code and m:
                level = len(m.group(1))
                text = m.group(2).strip().lower()
                if not found and sec in text:
                    found = True
                    target_level = level
                    extracted.append(line)
                elif found and level <= target_level:
                    break
                elif found:
                    extracted.append(line)
            elif found:
                extracted.append(line)

        if found:
            print('\n'.join(extracted).strip())
            sys.exit(0)
        else:
            print(f"Section '{opts['section']}' not found")
            sys.exit(1)

    if opts['filter']:
        headings = [h for h in headings if re.search(opts['filter'], h['text'], re.IGNORECASE)]
    if opts['level']:
        headings = [h for h in headings if h['level'] == opts['level']]

    if opts['count']:
        count_headings(headings)
        sys.exit(0)

    if opts['tree']:
        tree_printer(headings)
        sys.exit(0)

    if opts['list']:
        if opts['output'] == 'json':
            print(json.dumps({
                "document": {
                    "metadata": {
                        "source": None,
                        "headingCount": len(headings),
                        "maxDepth": max([h['level'] for h in headings]) if headings else 0,
                        "wordCount": len(content.split())
                    },
                    "sections": [
                        {
                            "id": h['raw_text'].lower().replace(' ', '-'),
                            "level": h['level'],
                            "title": h['raw_text'],
                            "slug": h['raw_text'].lower().replace(' ', '-'),
                            "position": {"line": 0, "offset": 0},
                            "content": {"raw": "", "blocks": []},
                            "children": []
                        } for h in headings
                    ]
                }
            }, indent=2))
        else:
            for h in headings:
                print(h['text'])
        sys.exit(0)

    if opts['query']:
        import query_engine
        res = query_engine.evaluate_query(opts['query'], content.splitlines())
        for r in res:
            print(r)
        sys.exit(0)

if __name__ == '__main__':
    main()
